-- Isolated SPM-177 migration test schema, reused from the SPM-36 reduced fixture.
-- Originally based on the exposed development schema
-- inspected on 19 October 2026. This fixture captures columns and relationships;
-- it is not a complete production schema or deployment baseline. Existing helper
-- functions and triggers are loaded from their real migrations by the test.
-- No Auth or provider service is simulated by these SQL engine tests.

CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role;

CREATE TYPE public.user_role AS ENUM ('ORGANISER', 'COORDINATOR', 'VENUE_STAFF', 'TECH_SUPPORT', 'ATTENDEE', 'COORDINATOR_LEAD', 'SAFETY_OFFICER');

CREATE TYPE public.event_status AS ENUM ('DRAFT', 'SUBMITTED', 'UNDER_REVIEW', 'AWAITING_CLARIFICATION', 'APPROVED', 'PLANNING', 'SAFETY_REVIEW', 'CONFIRMED', 'PREPARATION', 'COMPLETED', 'CANCELLED', 'REJECTED');

CREATE TYPE public.notification_type AS ENUM ('STATUS_CHANGE', 'BOOKING_UPDATE', 'EQUIPMENT_UPDATE', 'REGISTRATION_ALERT');

CREATE TABLE public."user" (
  "user_id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "email" text NOT NULL,
  "name" text NOT NULL,
  "phone" text,
  "role" public.user_role NOT NULL,
  "created_at" timestamptz DEFAULT now() NOT NULL,
  "auth_user_id" uuid,
  "is_active" boolean DEFAULT true NOT NULL,
  PRIMARY KEY ("user_id")
);

CREATE TABLE public."organisation" (
  "organisation_id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" text NOT NULL,
  "created_at" timestamptz DEFAULT now() NOT NULL,
  PRIMARY KEY ("organisation_id")
);

CREATE TABLE public."organisation_membership" (
  "organisation_id" integer NOT NULL,
  "user_id" integer NOT NULL,
  "created_at" timestamptz DEFAULT now() NOT NULL,
  PRIMARY KEY ("organisation_id", "user_id")
);

CREATE TABLE public."event" (
  "event_id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "organiser_id" integer NOT NULL,
  "coordinator_id" integer,
  "title" text NOT NULL,
  "purpose" text,
  "description" text,
  "status" public.event_status DEFAULT 'DRAFT' NOT NULL,
  "start_datetime" timestamptz,
  "end_datetime" timestamptz,
  "expected_attendance" integer,
  "accessibility_needs" text,
  "is_registration_enabled" boolean DEFAULT false NOT NULL,
  "registration_capacity" integer,
  "created_at" timestamptz DEFAULT now() NOT NULL,
  "updated_at" timestamptz DEFAULT now() NOT NULL,
  "preferred_layout_type" text,
  "is_published" boolean DEFAULT false NOT NULL,
  "registration_open_at" timestamptz,
  "registration_close_at" timestamptz,
  "organisation_id" integer,
  "version" integer DEFAULT 1 NOT NULL,
  "arrangement_version" integer DEFAULT 1 NOT NULL,
  "previously_confirmed" boolean DEFAULT false NOT NULL,
  PRIMARY KEY ("event_id")
);

CREATE TABLE public."venue" (
  "venue_id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" text NOT NULL,
  "address" text NOT NULL,
  "max_capacity" integer NOT NULL,
  "operating_hours" text,
  "accessibility_features" text,
  "setup_turnaround_min" integer,
  "is_active" boolean DEFAULT true NOT NULL,
  PRIMARY KEY ("venue_id")
);

CREATE TABLE public."room" (
  "room_id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "venue_id" integer NOT NULL,
  "layout_type" text NOT NULL,
  "capacity" integer NOT NULL,
  PRIMARY KEY ("room_id")
);

CREATE TABLE public."equipment" (
  "equipment_id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" text NOT NULL,
  "category" text NOT NULL,
  "description" text,
  "total_quantity" integer DEFAULT 0 NOT NULL,
  PRIMARY KEY ("equipment_id")
);

CREATE TABLE public."event_venue_preference" (
  "event_id" integer NOT NULL,
  "venue_id" integer NOT NULL,
  "preference_order" integer NOT NULL,
  PRIMARY KEY ("event_id", "venue_id")
);

CREATE TABLE public."event_equipment_requirement" (
  "event_id" integer NOT NULL,
  "equipment_id" integer NOT NULL,
  "quantity_requested" integer NOT NULL,
  PRIMARY KEY ("event_id", "equipment_id")
);

CREATE TABLE public."event_assignments" (
  "assignment_id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "event_id" integer NOT NULL,
  "coordinator_id" integer NOT NULL,
  "assigned_by" integer,
  "assigned_at" timestamptz DEFAULT now() NOT NULL,
  "ended_at" timestamptz,
  "reason" text,
  PRIMARY KEY ("assignment_id")
);

CREATE TABLE public."notification" (
  "notification_id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "event_id" integer,
  "title" text NOT NULL,
  "message" text NOT NULL,
  "type" public.notification_type NOT NULL,
  "created_at" timestamptz DEFAULT now() NOT NULL,
  PRIMARY KEY ("notification_id")
);

CREATE TABLE public."notification_recipient" (
  "notification_id" integer NOT NULL,
  "recipient_id" integer NOT NULL,
  "is_read" boolean DEFAULT false NOT NULL,
  "read_at" timestamptz,
  PRIMARY KEY ("notification_id", "recipient_id")
);

CREATE TABLE public."activity_log" (
  "log_id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" integer,
  "entity_name" text NOT NULL,
  "entity_id" integer NOT NULL,
  "action" text NOT NULL,
  "details" text,
  "timestamp" timestamptz DEFAULT now() NOT NULL,
  "actor_role" text,
  "changes" jsonb,
  "audience" text NOT NULL,
  PRIMARY KEY ("log_id")
);

ALTER TABLE public."organisation_membership" ADD FOREIGN KEY ("organisation_id") REFERENCES public."organisation"("organisation_id");

ALTER TABLE public."organisation_membership" ADD FOREIGN KEY ("user_id") REFERENCES public."user"("user_id");

ALTER TABLE public."event" ADD FOREIGN KEY ("organiser_id") REFERENCES public."user"("user_id");

ALTER TABLE public."event" ADD FOREIGN KEY ("coordinator_id") REFERENCES public."user"("user_id");

ALTER TABLE public."event" ADD FOREIGN KEY ("organisation_id") REFERENCES public."organisation"("organisation_id");

ALTER TABLE public."room" ADD FOREIGN KEY ("venue_id") REFERENCES public."venue"("venue_id");

ALTER TABLE public."event_venue_preference" ADD FOREIGN KEY ("event_id") REFERENCES public."event"("event_id");

ALTER TABLE public."event_venue_preference" ADD FOREIGN KEY ("venue_id") REFERENCES public."venue"("venue_id");

ALTER TABLE public."event_equipment_requirement" ADD FOREIGN KEY ("event_id") REFERENCES public."event"("event_id");

ALTER TABLE public."event_equipment_requirement" ADD FOREIGN KEY ("equipment_id") REFERENCES public."equipment"("equipment_id");

ALTER TABLE public."event_assignments" ADD FOREIGN KEY ("event_id") REFERENCES public."event"("event_id");

ALTER TABLE public."event_assignments" ADD FOREIGN KEY ("coordinator_id") REFERENCES public."user"("user_id");

ALTER TABLE public."event_assignments" ADD FOREIGN KEY ("assigned_by") REFERENCES public."user"("user_id");

ALTER TABLE public."notification" ADD FOREIGN KEY ("event_id") REFERENCES public."event"("event_id");

ALTER TABLE public."notification_recipient" ADD FOREIGN KEY ("notification_id") REFERENCES public."notification"("notification_id");

ALTER TABLE public."notification_recipient" ADD FOREIGN KEY ("recipient_id") REFERENCES public."user"("user_id");

ALTER TABLE public."activity_log" ADD FOREIGN KEY ("user_id") REFERENCES public."user"("user_id");

ALTER TABLE public.event_equipment_requirement ADD CHECK (quantity_requested > 0);

ALTER TABLE public.event ADD CHECK (expected_attendance IS NULL OR expected_attendance > 0);

ALTER TABLE public.event ADD CHECK (end_datetime IS NULL OR start_datetime IS NULL OR end_datetime > start_datetime);
